// Writes src/server/pdf/font-data.generated.ts: the catalogue and receipt PDF
// fonts as base64 data URLs, so react-pdf can use them without a filesystem
// (Cloudflare Workers has none). Run after changing a file in
// src/server/pdf/fonts:  node scripts/generate-pdf-font-data.mjs
// tests/pdf/font-data.test.ts fails if the generated file is out of date.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const dir = path.join(root, "src/server/pdf/fonts");
const out = path.join(root, "src/server/pdf/font-data.generated.ts");

const files = readdirSync(dir).filter((f) => f.endsWith(".ttf")).sort();
const lines = files.map((f) => `  ${JSON.stringify(f)}: "data:font/ttf;base64,${readFileSync(path.join(dir, f)).toString("base64")}",`);

writeFileSync(
  out,
  `// GENERATED by scripts/generate-pdf-font-data.mjs from src/server/pdf/fonts/*.ttf. Do not edit.
// Fonts: SIL Open Font License (see src/server/pdf/fonts/LICENSE-*).
export const FONT_DATA_URLS: Record<string, string> = {
${lines.join("\n")}
};
`,
);
console.log(`Wrote ${path.relative(root, out)} (${files.length} fonts)`);
